@js:var xid=baseUrl.match(/(\d+)\.html/)[1];
var html=java.ajax('https://www.fanren7.com/ajax.php?my=url2disk&xid='+xid);
var a=html.indexOf('<div id="bodybox">');
var b=html.indexOf('</div>{697}',a);
var body=a>=0&&b>a?html.substring(a+18,b):'';
var ps=body.split('<p>');
var out=[];
for(var i=1;
i<ps.length;
i++){var t=ps[i].split('</p>')[0].replaceAll('<[^>]+>','').trim();
if(t=='')continue;
if(t.indexOf('第')>-1&&t.indexOf('/')>-1&&t.indexOf('页')>-1)continue;
if(t.indexOf('本章未完')>-1)continue;
out.push(t)}out.join('\n');

